  "ch10.ctl.cf": "Capacity factor",
  "ch10.ctl.skew": "Router skew",
  "ch10.btn.balance": "Start balancing",
  "ch10.btn.stop": "Stop balancing",
  "ch10.btn.reset": "Reset",
  "ch10.read.drop": "Dropped assignments",
